SELECT i_item_id, i_product_name, i_current_price, i_wholesale_cost, i_current_price - i_wholesale_cost AS price_margin, CASE WHEN i_current_price > i_wholesale_cost * 1.2 THEN 'High margin' WHEN i_current_price > i_wholesale_cost * 1.0 THEN 'Medium margin' ELSE 'Low margin' END AS margin_category, i_brand || ' ' || i_category AS brand_category, p_promo_name, p_cost, p_cost / NULLIF(i_current_price, 0) AS cost_ratio, CASE WHEN p_discount_active = 'N' THEN 'Discounted' ELSE 'Regular' END AS promo_status, p_start_date_sk, p_end_date_sk FROM promotion JOIN item ON promotion.p_item_sk = item.i_item_sk WHERE i_category_id = 10 AND p_start_date_sk >= 2450577 AND p_discount_active = 'N'
